changeSet.sql:
GRANT EXECUTE ON FUNCTION nexus.assign_from_chashes_384(text, text[], boolean)  TO nexus_svc;
GRANT EXECUTE ON FUNCTION nexus.assign_from_chashes_768(text, text[], boolean)  TO nexus_svc;
